class _RowFocusHost(ConsolidatedCSSApp):
    """Mount a bare Vertical of mixed rows/non-row siblings.

    Mirrors the Skills list canvas's exact shape (``library_skills_canvas.py``
    interleaves a non-row ``Static`` secondary line between some rows), in
    isolation from the full ``LibraryScreen`` -- ``_move_library_list_row_focus``
    is a pure module-level function precisely so it can be proven correct
    this way (see its docstring).
    """

    def compose(self) -> ComposeResult:
        with Vertical():
            yield Button("Row 0", id="row-0", classes="library-skill-row")
            yield Static("flags · description", classes="library-skill-row-secondary")
            yield Button("Row 1", id="row-1", classes="library-skill-row")
            yield Button("Row 2", id="row-2", classes="library-skill-row")
            yield Static("flags · description", classes="library-skill-row-secondary")


@pytest.mark.asyncio
async def test_move_library_list_row_focus_skips_interleaved_non_row_siblings():
    """The Skills list interleaves a non-row ``Static`` secondary line
    between some rows -- a plain "next DOM child" walk would land on that
    Static (which cannot take focus) every other step instead of the next
    row. ``_move_library_list_row_focus`` filters siblings to the row
    class first, so Down/Up always land on the next/previous ROW."""
    app = _RowFocusHost()
    async with app.run_test() as pilot:
        row0 = app.query_one("#row-0", Button)
        row1 = app.query_one("#row-1", Button)
        row2 = app.query_one("#row-2", Button)
        row0.focus()
        await pilot.pause()

        assert (
            library_screen_module._move_library_list_row_focus(app.focused, "down")
            is True
        )
        await pilot.pause()
        assert row1.has_focus

        assert (
            library_screen_module._move_library_list_row_focus(app.focused, "down")
            is True
        )
        await pilot.pause()
        assert row2.has_focus

        # Boundary: Down at the last row is claimed (True) but does not wrap.
        assert (
            library_screen_module._move_library_list_row_focus(app.focused, "down")
            is True
        )
        await pilot.pause()
        assert row2.has_focus

        assert (
            library_screen_module._move_library_list_row_focus(app.focused, "up")
            is True
        )
        await pilot.pause()
        assert row1.has_focus


def test_move_library_list_row_focus_ignores_non_row_and_absent_focus():
    """Up/Down must be left untouched (return False) when the currently
    focused widget is not a Library list row, and when nothing is
    focused -- the ``on_key`` caller relies on this to leave the key alone
    for its normal handling everywhere else on the screen."""
    plain_button = Button("Not a list row")
    assert (
        library_screen_module._move_library_list_row_focus(plain_button, "down")
        is False
    )
    assert library_screen_module._move_library_list_row_focus(None, "down") is False


# Gated fakes block a real executor thread on a threading.Event until a test
# releases it. A test that fails (or forgets to release) before that point
# would leave the thread parked on an unbounded ``Event.wait()`` -- and the
# asyncio default executor joins its threads at loop/interpreter shutdown, so
# one un-released gate wedges the WHOLE pytest process at exit with no output
# (observed: three full-suite runs hung in ``wait_for_thread_shutdown``). A
# generous bound lets the thread free itself so shutdown always completes;
# passing tests release within milliseconds, far inside this window.
_GATED_RELEASE_TIMEOUT_SECONDS = 30.0


@pytest.fixture(autouse=True)
def _stub_library_search_history_cli_fallback(monkeypatch):
    """Isolate ``LibraryScreen`` construction from the real on-disk CLI config.

    ``_load_library_search_history`` falls back to ``get_cli_setting`` when
    ``app_config`` has no in-memory history yet (the Issue 1 fix: recover
    persisted history after a restart). Tests share one real ``HOME`` /
    ``config.toml`` across the whole pytest session -- other tests'
    ``_record_library_search_history`` calls persist to that same file via
    a background ``save_setting_to_cli_config`` worker -- so without this
    stub, a freshly constructed screen would non-deterministically inherit
    whatever ``[library.search] history`` a prior test (or prior session)
    happened to leave on disk instead of starting clean. Tests that want to
    exercise the CLI-config fallback itself re-patch
    ``library_screen_module.get_cli_setting`` after this fixture runs, which
    takes precedence for the remainder of the test.

    This blanket stub (it returns ``None`` for *any* ``get_cli_setting``
    call, not just ``"library.search"``) also isolates
    ``_library_rail_preferences``'s own ``get_cli_setting("library.rail_state")``
    fallback (C4) from the same on-disk leakage, for the same reason --
    tests that exercise *that* fallback specifically also re-patch
    ``library_screen_module.get_cli_setting`` after this fixture runs.
    """
    monkeypatch.setattr(
        library_screen_module, "get_cli_setting", lambda *args, **kwargs: None
    )


class LibraryHarness(ConsolidatedCSSApp):
    """Mount a single LibraryScreen with the real app stylesheet."""

    CSS_PATH = str(
        Path(__file__).resolve().parents[2]
        / "tldw_chatbook"
        / "css"
        / "tldw_cli_modular.tcss"
    )

    def __init__(self, app_instance, seen_routes=None, screen=None):
        super().__init__()
        self.app_instance = app_instance
        self.seen_routes = seen_routes if seen_routes is not None else []
        self.seen_contexts = []
        self._screen = screen

    async def on_mount(self) -> None:
        await self.push_screen(self._screen or LibraryScreen(self.app_instance))

    def on_navigate_to_screen(self, message) -> None:
        self.seen_routes.append(message.screen_name)
        self.seen_contexts.append(dict(message.screen_context or {}))


class _ConversationCanvasHarness(App):
    """Mount the conversations canvas with the production stylesheet."""

    CSS_PATH = LibraryHarness.CSS_PATH

    def __init__(self, canvas: LibraryConversationsCanvasState) -> None:
        super().__init__()
        self.canvas = canvas

    def compose(self) -> ComposeResult:
        yield LibraryConversationsCanvas(
            self.canvas,
            id="library-conversations-canvas",
        )


@pytest.mark.asyncio
async def test_conversation_canvas_scrolls_current_page_while_pager_stays_fixed():
    """A full page scrolls at 100x30 while its pager remains a canvas sibling."""
    canvas = LibraryConversationsCanvasState(
        rows=tuple(
            LibraryConversationRow(
                conversation_id=str(index),
                title=f"Conversation {index}",
                secondary="1 message",
                selected=index == 0,
            )
            for index in range(1, 21)
        ),
        status_copy="",
        empty_copy="",
        selected_id="1",
        preview_lines=("Conversation 1", "Messages: 1", "Updated: now"),
        query="",
        range_copy="1-20 of 20",
        page_copy="Page 1 of 1",
        previous_disabled=True,
        next_disabled=True,
    )
    app = _ConversationCanvasHarness(canvas)

    async with app.run_test(size=(100, 30)) as pilot:
        scroll = app.query_one("#library-conversations-list", VerticalScroll)
        pager = app.query_one("#library-conversations-pager")
        previous = app.query_one("#library-conversations-previous", Button)
        next_page = app.query_one("#library-conversations-next", Button)
        status = app.query_one("#library-conversations-page-status", Static)

        assert scroll.max_scroll_y > 0
        assert previous.disabled is True
        assert next_page.disabled is True
        assert str(status.renderable) == "1-20 of 20 · Page 1 of 1"
        assert pager.parent is scroll.parent
        assert pager.parent is not scroll

        last_row = app.query_one("#library-conversation-row-19", Button)
        last_row.focus()
        await pilot.pause()
        assert scroll.scroll_y > 0


@pytest.mark.asyncio
async def test_conversation_canvas_pager_stays_in_the_visible_library_host():
    """The production canvas must not claim the grid's fractional width again."""
    app = _build_test_app()
    _seed_conversations(
        app,
        [
            {
                "title": f"Conversation {index}",
                "conversation_id": f"chat-{index}",
                "message_count": 1,
                "updated_at": "2026-06-01T10:00:00Z",
            }
            for index in range(20)
        ],
    )
    host = LibraryHarness(app)

    async with host.run_test(size=(100, 30)) as pilot:
        screen = _active_library_screen(host)
        await _wait_for_library_shell(screen, pilot)
        screen.query_one("#library-row-browse-conversations", Button).press()
        await _wait_for_selector(screen, pilot, "#library-conversation-row-19")

        canvas_host = screen.query_one("#library-canvas")
        canvas = screen.query_one("#library-conversations-canvas")
        scroll = screen.query_one("#library-conversations-list", VerticalScroll)
        pager = screen.query_one("#library-conversations-pager")
        pager_status = screen.query_one("#library-conversations-page-status", Static)
        previous = screen.query_one("#library-conversations-previous", Button)
        next_page = screen.query_one("#library-conversations-next", Button)

        def assert_within_canvas(widget) -> None:
            assert widget.region.x >= canvas_host.region.x
            assert widget.region.right <= canvas_host.region.right

        assert_within_canvas(canvas)
        for widget in (scroll, pager, pager_status, previous, next_page):
            assert_within_canvas(widget)
        assert scroll.max_scroll_y > 0

        pager_region = pager.region
        last_row = screen.query_one("#library-conversation-row-19", Button)
        last_row.focus()
        await pilot.pause()
        assert scroll.scroll_y > 0
        assert pager.region == pager_region

        # The only-page state rightly disables both controls. Enable each
        # independently here to prove its compact pager geometry still admits
        # normal focus when Task 3 supplies a navigable page.
        previous.disabled = False
        previous.focus()
        await pilot.pause()
        assert previous.has_focus
        next_page.disabled = False
        next_page.focus()
        await pilot.pause()
        assert next_page.has_focus


def _active_library_screen(host: LibraryHarness):
    return host.screen_stack[-1]


def _visible_text(screen) -> str:
    chunks = []
    for widget in screen.query("Static"):
        renderable = getattr(widget, "renderable", "")
        chunks.append(getattr(renderable, "plain", str(renderable)))
    for widget in screen.query("Button"):
        label = getattr(widget, "label", "")
        chunks.append(str(label) if label is not None else "")
    return " ".join(chunks)


def _seed_conversations(app, conversations, *, notes=None, media=None, highlights=None):
    app.notes_scope_service = StaticLibraryNotesScopeService(notes or [])
    # Production local-note detail obtains keywords from this separate service.
    # Keep the fake contract coherent for notes created during a test, whose
    # detail record intentionally carries no inline ``keywords`` field.
    app.notes_service = StaticLibraryNotesKeywordsService({})
    app.media_reading_scope_service = StaticLibraryMediaScopeService(
        media or [], highlights=highlights
    )
    app.chat_conversation_scope_service = StaticLibraryConversationScopeService(
        conversations
    )


def _normalised_cli_lookup(*args, **kwargs) -> tuple[str, str]:
    """Reduce any ``get_cli_setting`` call shape to a ``(section, key)`` pair.

    That helper accepts both ``get_cli_setting("library", "search", default)``
    and the dotted ``get_cli_setting("library.search")``. Matching on the raw
    first argument therefore only catches whichever shape the code happens to
    use today: a switch to the two-argument form would make a precedence test
    silently stop detecting the fallback it exists to detect. Keyword calls are
    read too, so a caller moving to keywords cannot make this raise IndexError
    instead of failing usefully.

    Returns:
        ``(section, key)`` lowercased, with a dotted section split on its first
        dot. An unparseable call yields ``("", "")``, which matches nothing.
    """
    section = kwargs.get("section")
    key = kwargs.get("key")
    positional = list(args)
    if section is None and positional:
        section = positional.pop(0)
    if key is None and positional:
        key = positional.pop(0)
    section = str(section or "")
    if "." in section:
        # Dotted shape: the second slot carries the default, not a key.
        section, _, key = section.partition(".")
    return section.strip().lower(), str(key or "").strip().lower()


async def _wait_for_library_shell(screen, pilot, *, attempts=120, timeout=15.0):
    """Await the Library shell being loaded with its rail mounted.

    Bounded by WALL CLOCK, not by a pause count. ``attempts`` alone measured
    iterations of ``pilot.pause(0.02)``, and a pause takes as long as the event
    loop needs -- so on a loaded machine the same 120 iterations buy far less
    real time than they appear to, and the helper reports "never loaded" for a
    shell that was merely slow. That is how this file's failures moved around
    with machine load (task-699); ``_wait_for_condition`` below already used a
    wall-clock budget for the same reason.

    ``attempts`` is kept as a floor so a caller that deliberately passes a small
    number still gets at least that many polls.
    """
    # One effective budget, so the reported deadline is the real one. ``attempts``
    # only raises the floor for a caller that wants more polls than the timeout
    # would allow; it never extends the wait past its own stated bound, which the
    # first version did by keeping the loop alive on ``polls < attempts``.
    budget = max(timeout, attempts * 0.02)
    deadline = time.monotonic() + budget
    polls = 0
    while True:
        # Condition FIRST, deadline second -- mirroring ``_wait_for_condition``.
        # Checking the deadline in the loop header instead means a ``pilot.pause``
        # that overshoots it exits without re-testing, so a shell that finished
        # loading *during* that pause is reported as never loaded: a false
        # timeout, and exactly the class of flake this helper exists to avoid.
        if getattr(screen, "_library_loaded", False) and screen.query("#library-rail"):
            await pilot.pause()
            await pilot.pause()
            return
        if time.monotonic() >= deadline:
            break
        await pilot.pause(0.02)
        polls += 1
    raise AssertionError(
        f"Library shell never loaded within {budget:.1f}s ({polls} polls). "
        f"Visible text: {_visible_text(screen)}"
    )


async def _wait_for_selector(screen, pilot, selector, *, attempts=120, timeout=15.0):
    """Await ``selector`` mounting. Wall-clock bounded -- see
    ``_wait_for_library_shell`` for why a pause count is not a time budget."""
    budget = max(timeout, attempts * 0.02)
    deadline = time.monotonic() + budget
    polls = 0
    while True:
        matches = list(screen.query(selector))
        if matches:
            await pilot.pause()
            return matches[0]
        if time.monotonic() >= deadline:
            break
        await pilot.pause(0.02)
        polls += 1
    raise AssertionError(
        f"{selector} never mounted within {budget:.1f}s ({polls} polls). "
        f"Visible text: {_visible_text(screen)}"
    )


async def _wait_for_display(screen, pilot, selector, *, attempts=120):
    """Wait until an always-mounted stable-composition widget is visible."""
    widget = await _wait_for_selector(screen, pilot, selector, attempts=attempts)
    for _ in range(attempts):
        if widget.display:
            await pilot.pause()
            return widget
        await pilot.pause(0.02)
    raise AssertionError(
        f"{selector} never became visible. Visible text: {_visible_text(screen)}"
    )


def _widget_text(widget) -> str:
    """Render a widget's visible text for a poll loop's failure message."""
    for attribute in ("label", "renderable"):
        if hasattr(widget, attribute):
            return str(getattr(widget, attribute))
    return repr(widget)


async def _wait_for_widget_state(
    screen,
    pilot,
    selector,
    predicate,
    *,
    what,
    attempts=150,
    interval=0.02,
    describe=_widget_text,
):
    """Poll ``selector`` until ``predicate(widget)`` holds, tolerating gaps.

    (task-14800) When the change a poll loop waits for is DELIVERED BY a
    recompose, the node it reads is transiently unmounted for one or more
    ticks. A bare ``query_one`` in the loop body raises ``NoMatches`` in that
    window instead of retrying, so the test dies on the gap -- naming the
    wrong defect -- long before its own attempt budget is reached. Query
    tolerantly here, keep the budget as the ONLY failure signal, and report
    the last value actually observed so a real stall still says what it saw.

    Args:
        screen: Screen to query.
        pilot: Textual pilot used to pause between attempts.
        selector: CSS selector for the polled widget.
        predicate: Called with the matched widget; truthy ends the wait.
        what: Failure sentence used when the budget runs out.
        attempts: Maximum number of polls.
        interval: Seconds to pause between polls.
        describe: Renders the observed widget for the failure message.

    Returns:
        The matched widget once ``predicate`` holds.

    Raises:
        AssertionError: If the predicate never holds within the budget.
    """
    last_observed = "<no node matched the selector>"
    for _ in range(attempts):
        matches = screen.query(selector)
        if matches:
            widget = matches.first()
            last_observed = describe(widget)
            if predicate(widget):
                return widget
        await pilot.pause(interval)
    raise AssertionError(f"{what} (last observed: {last_observed!r})")


async def _wait_for_condition(
    pilot, predicate, *, timeout=15.0, message, interval=0.02
) -> None:
    """Await until ``predicate()`` is truthy, or raise once ``timeout`` wall-clock seconds elapse.

    A deadline (not a fixed iteration count) so the wait survives CPU contention
    yet returns the instant the condition is met. ``message`` may be a string or a
    zero-arg callable (evaluated at raise time, so dynamic diagnostics report the
    stuck state).

    The predicate is checked FIRST each iteration -- before the deadline test and
    before pausing -- so it is evaluated at least once (even at ``timeout=0``) and
    is always given a final chance after a ``pause`` that overshoots the deadline
    under contention (which is exactly when a state transition it is waiting for
    may have just landed).
    """
    deadline = time.monotonic() + timeout
    while True:
        if predicate():
            return
        if time.monotonic() >= deadline:
            break
        await pilot.pause(interval)
    raise AssertionError(message() if callable(message) else message)


async def _wait_for_worker_group_to_drain(
    host, pilot, screen, group: str, *, timeout: float = 15.0
) -> None:
    """Wait for one screen-owned worker group without draining unrelated work."""

    await _wait_for_condition(
        pilot,
        lambda: not any(
            worker.node is screen and worker.group == group for worker in host.workers
        ),
        timeout=timeout,
        message=f"Worker group {group!r} never drained.",
    )


class _FakePilot:
    """Minimal pilot stand-in for unit-testing _wait_for_condition (pause is a no-op, but counted)."""

    def __init__(self) -> None:
        self.pause_calls = 0

    async def pause(self, delay: float = 0) -> None:
        self.pause_calls += 1
        return None


@pytest.mark.asyncio
async def test__wait_for_condition_returns_immediately_when_true() -> None:
    """An already-true predicate returns on the first check, without ever pausing."""
    calls = {"n": 0}

    def pred() -> bool:
        calls["n"] += 1
        return True

    pilot = _FakePilot()
    await _wait_for_condition(pilot, pred, message="must not raise")
    assert calls["n"] == 1  # checked once...
    assert pilot.pause_calls == 0  # ...and returned before ever pausing


@pytest.mark.asyncio
async def test__wait_for_condition_checks_predicate_before_raising() -> None:
    """The predicate is checked at least once before the deadline is enforced, so a
    condition that is already satisfied returns even when the deadline has elapsed
    (guards against a false timeout when a pause overshoots the deadline)."""
    pilot = _FakePilot()
    await _wait_for_condition(
        pilot, lambda: True, timeout=0.0, message="must not raise"
    )
    assert pilot.pause_calls == 0


@pytest.mark.asyncio
async def test__wait_for_condition_raises_with_message_on_timeout() -> None:
    """A never-true predicate raises AssertionError carrying the given message on timeout."""
    with pytest.raises(AssertionError, match="boom"):
        await _wait_for_condition(
            _FakePilot(), lambda: False, timeout=0.05, message="boom"
        )


@pytest.mark.asyncio
async def test__wait_for_condition_evaluates_callable_message_at_raise() -> None:
    """A callable message is evaluated at raise time (so dynamic diagnostics report the stuck state)."""
    with pytest.raises(AssertionError, match="dynamic 42"):
        await _wait_for_condition(
            _FakePilot(),
            lambda: False,
            timeout=0.05,
            message=lambda: f"dynamic {6 * 7}",
        )


