# --- Ingest canvas (L3b Task 4) --------------------------------------------
#
# Unlike ``LibraryHarness`` (whose ``app_instance`` is a separate, never-run
# ``TldwCli``), submitting a real ingest job needs ``self.app_instance`` to
# literally be the running app: ``submit_library_ingest_job`` starts an
# ``@work``-decorated background worker and marshals every registry
# mutation back via ``call_from_thread`` -- neither works without a live
# message pump. ``_LibraryIngestCanvasHarness`` mixes the real
# ``LibraryIngestQueueMixin`` (app.py) straight into a minimal running
# ``App`` and pushes ``LibraryScreen(self)`` -- mirroring
# ``_IngestRunnerHarness`` (Tests/Library/test_library_ingest_runner.py)
# combined with ``LibraryHarness``'s screen-hosting shape. Notes/
# conversations use the existing static empty fakes purely so
# ``_list_local_source_snapshot`` doesn't bail into its lookup-error state
# (which would otherwise blank out the media viewer on Open in Library);
# only Media needs to be real here, wired to the SAME db the ingest
# queue-runner writes to.

_INGEST_POLL_ATTEMPTS = 500
_INGEST_POLL_INTERVAL = 0.02


class _LibraryIngestCanvasHarness(LibraryIngestQueueMixin, App):
    """Runs a real LibraryScreen against a running app mixing the real
    ingest coordinator + writer + registry + an optional real file-backed
    MediaDatabase.

    Defaults to an auto-run ``_FakeIngestParsePool`` (F3) -- real
    ``run_parse_job``/``persist_parsed_media``, fake pool -- so the ~20
    ingest pilots below never spawn real OS processes. Pass
    ``pool_factory``/``worker_count`` for pilots needing manual completion
    control or a specific backpressure cap (mirrors
    ``Tests/Library/test_library_ingest_runner.py``'s
    ``_IngestRunnerHarness``)."""

    CSS_PATH = str(
        Path(__file__).resolve().parents[2]
        / "tldw_chatbook"
        / "css"
        / "tldw_cli_modular.tcss"
    )

    def __init__(self, media_db, *, pool_factory=None, worker_count=None):
        super().__init__()
        # task-3315: the runtime-state contract is DERIVED from the app's own
        # initializer, never hand-listed -- the hand-listed version missed
        # `_ingest_local_stt_jobs` when the local-STT lane landed and ~20
        # pilots died with AttributeError inside `_top_up_ingest_parse_pool`.
        # Guarded by test_ingest_canvas_harness_mirrors_every_mixin_state_read.
        self._init_library_ingest_runtime_state()
        self.media_db = media_db
        self._pool_factory = pool_factory or (lambda: _FakeIngestParsePool())
        self._worker_count_override = worker_count
        self.notes_scope_service = StaticLibraryNotesScopeService([])
        self.chat_conversation_scope_service = StaticLibraryConversationScopeService([])
        if media_db is not None:
            self.media_reading_scope_service = MediaReadingScopeService(
                LocalMediaReadingService(media_db), None
            )

    def _create_ingest_parse_pool(self):
        return _IngestParsePoolResources(
            self._pool_factory(),
            queue.Queue(maxsize=64),
        )

    def _ingest_parse_worker_count(self) -> int:
        if self._worker_count_override is not None:
            return self._worker_count_override
        return super()._ingest_parse_worker_count()

    def library_rag_search_execution_lock(self) -> asyncio.Lock:
        lock = getattr(self, "_library_rag_search_execution_lock_instance", None)
        if lock is None:
            lock = asyncio.Lock()
            self._library_rag_search_execution_lock_instance = lock
        return lock

    async def on_mount(self) -> None:
        await self.push_screen(LibraryScreen(self))


def _library_ingest_mixin_state_reads() -> set[str]:
    """AST-derive every ingest-runtime attribute LibraryIngestQueueMixin reads.

    task-3315 guard input: the ingest coordinator/writer (``app.py``'s
    ``LibraryIngestQueueMixin``) reads host state like
    ``self._ingest_local_stt_jobs``; a harness that fakes the host but
    misses one of those attributes dies with AttributeError deep inside a
    pilot (the exact drift that broke ~20 job-lifecycle pilots here when
    the local-STT lane landed). This walks the mixin's AST and returns
    the ``_ingest_*`` / ``_local_stt_*`` / ``library_ingest_jobs`` names
    it loads (plain attribute reads and defensive ``getattr(self, ...)``
    reads), minus its own method names -- so the required set is derived
    from the real code, never hand-listed.
    """
    import tldw_chatbook.app as _app_module

    source = Path(_app_module.__file__).read_text(encoding="utf-8")
    module = ast.parse(source)
    mixin = next(
        node
        for node in module.body
        if isinstance(node, ast.ClassDef) and node.name == "LibraryIngestQueueMixin"
    )
    method_names = {
        node.name
        for node in mixin.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    def _wanted(name: str) -> bool:
        return (
            name.startswith(("_ingest_", "_local_stt_"))
            or name == "library_ingest_jobs"
        ) and name not in method_names

    reads: set[str] = set()
    for node in ast.walk(mixin):
        if (
            isinstance(node, ast.Attribute)
            and isinstance(node.value, ast.Name)
            and node.value.id == "self"
            and isinstance(node.ctx, ast.Load)
            and _wanted(node.attr)
        ):
            reads.add(node.attr)
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == "getattr"
            and len(node.args) >= 2
            and isinstance(node.args[0], ast.Name)
            and node.args[0].id == "self"
            and isinstance(node.args[1], ast.Constant)
            and isinstance(node.args[1].value, str)
            and _wanted(node.args[1].value)
        ):
            reads.add(node.args[1].value)
    assert reads, "AST derivation found no mixin state reads -- guard is vacuous"
    return reads


def test_ingest_canvas_harness_mirrors_every_mixin_state_read():
    """(task-3315 AC#3) The harness must carry every host attribute the real
    ingest job loop reads, DERIVED from the mixin's code -- when app.py grows
    a new ``self._ingest_*`` read, this fails naming it instead of ~20 pilots
    dying with AttributeError mid-run."""
    reads = _library_ingest_mixin_state_reads()

    harness = _LibraryIngestCanvasHarness(None)
    missing = sorted(name for name in reads if not hasattr(harness, name))
    assert not missing, (
        "harness does not mirror mixin state reads; missing attributes: "
        f"{missing}"
    )
    # ``media_db`` is the one documented host input outside the runtime-state
    # seam (a constructor argument, not coordinator state).
    assert hasattr(harness, "media_db")

    # The shared initializer must itself cover every read: apply it to a bare
    # object and require read-set coverage, so a new read in app.py that is
    # not added to ``_init_library_ingest_runtime_state`` fails HERE by name.
    bare = SimpleNamespace()
    LibraryIngestQueueMixin._init_library_ingest_runtime_state(bare)
    uninitialized = sorted(set(reads) - set(vars(bare)) - {"media_db"})
    assert not uninitialized, (
        "_init_library_ingest_runtime_state does not set every attribute the "
        f"mixin reads: {uninitialized}"
    )


async def _open_library_ingest_canvas(screen, pilot):
    # Wait for the row, not just press blind: a background ingest job landing
    # in `done` pokes the source snapshot, whose apply recomposes the rail --
    # the row is briefly unmounted mid-rebuild (surfaced by the F-010 landing
    # hub, which made that recompose reliably straddle this call).
    await _wait_for_selector(screen, pilot, "#library-row-ingest-import-media")
    screen.query_one("#library-row-ingest-import-media").press()
    await _wait_for_selector(screen, pilot, "#library-ingest-path")


@pytest.mark.asyncio
async def test_library_shell_ingest_canvas_happy_path_open_in_library(tmp_path):
    """(a) Full happy path: a real tmp .txt through a real file-backed
    MediaDatabase -- type the path, Start, poll until the row reaches
    done, then Open in Library lands in the media viewer on the item that
    was actually ingested."""
    db = MediaDatabase(tmp_path / "ingest-canvas.db", client_id="l3b-ingest-canvas")
    source = tmp_path / "tides.txt"
    source.write_text("Tides are driven by the moon's gravity.", encoding="utf-8")
    harness = _LibraryIngestCanvasHarness(db)

    async with harness.run_test(size=LIBRARY_TEST_SIZE) as pilot:
        screen = harness.screen_stack[-1]
        await _wait_for_library_shell(screen, pilot)
        await _open_library_ingest_canvas(screen, pilot)

        path_input = screen.query_one("#library-ingest-path", Input)
        path_input.value = str(source)
        await pilot.pause()

        start_button = screen.query_one("#library-ingest-start", Button)
        assert start_button.disabled is False
        start_button.press()
        await pilot.pause()

        # Path clears immediately on submit (metadata fields would persist).
        # A registry-driven targeted canvas refresh may briefly detach the
        # Input, so poll across that gap and assert the eventual rendered
        # control rather than only the screen-owned mirror.
        path_input = await _wait_for_widget_state(
            screen,
            pilot,
            "#library-ingest-path",
            lambda widget: isinstance(widget, Input) and widget.value == "",
            what="the rendered ingest path Input never cleared after submit",
        )
        assert path_input.value == ""

        # Task 4 has no live-update listener yet (that's Task 5) -- the
        # canvas only re-renders on a user-triggered recompose, so poll the
        # registry directly, then force one recompose once the job is done.
        for _ in range(_INGEST_POLL_ATTEMPTS):
            jobs = harness.library_ingest_jobs.jobs()
            if jobs and jobs[0].state == IngestJobState.DONE:
                break
            await pilot.pause(_INGEST_POLL_INTERVAL)
        else:
            raise AssertionError(
                f"Job never reached DONE: {harness.library_ingest_jobs.jobs()}"
            )

        screen.refresh(recompose=True)
        await pilot.pause()

        row_text = str(screen.query_one("#library-ingest-row-0").renderable)
        assert row_text.startswith("✓ done · tides.txt")
        # Row-action buttons are keyed by job_id, not row index (PR #591
        # review, F1) -- this is the first (only) job submitted against a
        # fresh registry, so its id is deterministically "ingest-job-1".
        assert screen.query_one("#library-ingest-open-ingest-job-1")

        screen.query_one("#library-ingest-open-ingest-job-1").press()
        for _ in range(_INGEST_POLL_ATTEMPTS):
            if screen._library_media_detail is not None:
                break
            await pilot.pause(_INGEST_POLL_INTERVAL)
        else:
            raise AssertionError("Media detail never loaded after Open in Library.")

        assert screen._library_media_view == "viewer"
        await _wait_for_selector(screen, pilot, "#library-media-viewer-title")
        viewer_title = str(screen.query_one("#library-media-viewer-title").renderable)
        assert "tides" in viewer_title.lower()


@pytest.mark.asyncio
async def test_library_shell_import_verb_pair_agrees_across_rail_canvas_and_toast(
    tmp_path,
):
    """(task-2857, Library UAT 2026-08-06 LIB-10) One flow, one verb: the
    rail row/top button say "Import…", the canvas they open is headed
    "Import media", and the completion toast says "Import finished" --
    not the pre-task-2857 mix of "Add content…" / "Import media" /
    "Ingest finished" that made the flow look like three different
    features."""
    db = MediaDatabase(tmp_path / "ingest-canvas.db", client_id="task-2857-verb-pair")
    source = tmp_path / "verb.txt"
    source.write_text("One verb pair end to end.", encoding="utf-8")
    harness = _LibraryIngestCanvasHarness(db)
    harness.notify = Mock()

    async with harness.run_test(size=LIBRARY_TEST_SIZE) as pilot:
        screen = harness.screen_stack[-1]
        await _wait_for_library_shell(screen, pilot)

        rail_row = screen.query_one("#library-row-ingest-import-media", Button)
        assert "Import…" in str(rail_row.label)

        await _open_library_ingest_canvas(screen, pilot)
        header = str(screen.query_one("#library-ingest-header").renderable)
        assert header == "Import media"

        start_button = screen.query_one("#library-ingest-start", Button)
        assert str(start_button.label) == "Start import"

        path_input = screen.query_one("#library-ingest-path", Input)
        path_input.value = str(source)
        await pilot.pause()
        start_button.press()
        await pilot.pause()

        for _ in range(_INGEST_POLL_ATTEMPTS):
            jobs = harness.library_ingest_jobs.jobs()
            if jobs and jobs[0].state == IngestJobState.DONE:
                break
            await pilot.pause(_INGEST_POLL_INTERVAL)
        else:
            raise AssertionError(
                f"Job never reached DONE: {harness.library_ingest_jobs.jobs()}"
            )
        await pilot.pause()

        summaries = [
            call.args[0]
            for call in harness.notify.call_args_list
            if call.args and str(call.args[0]).startswith("Import finished")
        ]
        assert summaries == ["Import finished — 1 imported"], (
            "rail says Import, canvas says Import media, but the toast "
            f"disagreed: {[c.args[0] for c in harness.notify.call_args_list if c.args]}"
        )


@pytest.mark.asyncio
async def test_library_shell_ingest_path_enter_submits_valid_form(tmp_path):
    """(task-186) Enter in the path field with a valid path starts the
    ingest exactly like the Start button. Enter on a blank path stays
    quiet (the gate line already explains the blocker) and submits
    nothing."""
    db = MediaDatabase(tmp_path / "ingest-canvas.db", client_id="l3b-ingest-canvas")
    source = tmp_path / "tides.txt"
    source.write_text("Tides are driven by the moon's gravity.", encoding="utf-8")
    harness = _LibraryIngestCanvasHarness(db)

    async with harness.run_test(size=LIBRARY_TEST_SIZE) as pilot:
        screen = harness.screen_stack[-1]
        await _wait_for_library_shell(screen, pilot)
        await _open_library_ingest_canvas(screen, pilot)

        path_input = screen.query_one("#library-ingest-path", Input)
        path_input.focus()
        await pilot.pause()

        # Blank path: Enter is a quiet no-op, nothing submitted.
        await pilot.press("enter")
        await pilot.pause()
